// Algebraic native RHS/finite-face checks using existing native jets only.
#include "goal1_native_algebraic_rhs.hpp"
#include "goal1_typed_support.hpp"
#include "goal1_native_face_boundary.hpp"
#include <fstream>
#include <vector>
#include <iostream>
#include <iomanip>
#include <string>
#include <cstdlib>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;
Real Read(){std::string s;if(!(std::cin>>s))throw std::runtime_error("short native algebraic point");char*e;Real x=std::strtod(s.c_str(),&e);if(*e||!std::isfinite(x))throw std::runtime_error("invalid point token");return x;}
h::Z4cRHS<Real> RHS(const std::array<Real,22>&r){h::Z4cRHS<Real>f{};f.chi=r[0];f.trace=r[7];f.theta=r[17];const int a[6]={0,0,0,1,1,2},b[6]={0,1,2,1,2,2};for(int k=0;k<6;++k){f.metric[a[k]][b[k]]=f.metric[b[k]][a[k]]=r[1+k];f.a[a[k]][b[k]]=f.a[b[k]][a[k]]=r[8+k];}for(int i=0;i<3;++i)f.lambda[i]=r[14+i];return f;}
Real MatrixDifference(const h::Z4cRHS<Real>&a,const h::Z4cRHS<Real>&b){Real e=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)e=std::max({e,fabs(a.metric[i][j]-b.metric[i][j]),fabs(a.a[i][j]-b.a[i][j])});return e;}
Real ScalarDifference(const h::Z4cRHS<Real>&a,const h::Z4cRHS<Real>&b){Real e=std::max({fabs(a.chi-b.chi),fabs(a.trace-b.trace),fabs(a.theta-b.theta)});for(int i=0;i<3;++i)e=std::max(e,fabs(a.lambda[i]-b.lambda[i]));return e;}
Real Trace(const h::MetricJet<Real>&g,const h::CurvatureJet<Real>&a){auto geo=h::Geometry(g);Real z=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)z+=geo.inverse[i][j]*a.k[i][j];return z;}
void Point(int id,int mode,h::Z4cJet<Real>u,const Real x[3]){h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);if(mode==1){u.theta.value+=.003;for(int i=0;i<3;++i)u.lambda.value[i]+=.002*(i+1);}auto rows=cs::typed_support::Core(u,p,rwm::ReferenceConnection(p,x));auto before=RHS(rows);if(mode==2){for(int i=0;i<3;++i)for(int j=0;j<3;++j){u.a.k[i][j]+=.03*(i+j+1);before.metric[i][j]=sin(Real(id+i+j+1));before.a[i][j]=cos(Real(id+i+j+2));}}
 auto f=before;auto d=cs::native_algebraic_rhs::Tangent(u.metric,u.a,f);if(!d.valid)throw std::runtime_error("invalid projection");auto again=f;cs::native_algebraic_rhs::Tangent(u.metric,u.a,again);Real fd[2][2]{};int pass=0;for(Real step:{Real(1e-4),Real(5e-5)}){auto gp=u.metric,gm=u.metric;auto ap=u.a,am=u.a;for(int i=0;i<3;++i)for(int j=0;j<3;++j){gp.g[i][j]+=step*f.metric[i][j];gm.g[i][j]-=step*f.metric[i][j];ap.k[i][j]+=step*f.a[i][j];am.k[i][j]-=step*f.a[i][j];}fd[pass][0]=(log(h::Geometry(gp).determinant)-log(h::Geometry(gm).determinant))/(2*step);fd[pass][1]=(Trace(gp,ap)-Trace(gm,am))/(2*step);++pass;}Real derivative=std::max(fabs((4*fd[1][0]-fd[0][0])/3),fabs((4*fd[1][1]-fd[0][1])/3));auto geo=h::Geometry(u.metric);Real naive=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)for(int k=0;k<3;++k)for(int l=0;l<3;++l)naive+=geo.inverse[i][k]*u.a.k[k][l]*geo.inverse[l][j]*f.metric[i][j];
 std::cout<<"{\"id\":"<<id<<",\"mode\":"<<mode<<",\"raw_metric_rate\":"<<d.metric_before<<",\"raw_A_rate\":"<<d.A_before<<",\"post_metric_rate\":"<<d.metric_after<<",\"post_A_rate\":"<<d.A_after<<",\"correction\":"<<std::max(d.metric_change,d.A_change)<<",\"idempotence\":"<<MatrixDifference(f,again)<<",\"other_native_rows_changed\":"<<ScalarDifference(before,f)<<",\"finite_difference_invariant_rate\":"<<derivative<<",\"negative_omit_moving_inverse\":"<<fabs(naive)<<",\"physical_theta\":"<<u.theta.value<<"}\n";}
h::Z4cJet<Real> Passive(const Real*data){h::Z4cJet<Real>u{};auto scalar=[&](int n){h::ScalarJet<Real>s{};const Real*p=data+14+n*13;s.value=p[0];for(int d=0;d<3;++d){s.d[d]=p[1+d];for(int e=0;e<3;++e)s.dd[d][e]=p[4+d*3+e];}return s;};u.chi=scalar(0);u.trace=scalar(7);u.theta=scalar(17);u.alpha=scalar(18);const int a[6]={0,0,0,1,1,2},b[6]={0,1,2,1,2,2};for(int k=0;k<6;++k){auto g=scalar(1+k),A=scalar(8+k);int i=a[k],j=b[k];u.metric.g[i][j]=u.metric.g[j][i]=g.value;u.a.k[i][j]=u.a.k[j][i]=A.value;for(int d=0;d<3;++d){u.metric.dg[d][i][j]=u.metric.dg[d][j][i]=g.d[d];u.a.dk[d][i][j]=u.a.dk[d][j][i]=A.d[d];for(int e=0;e<3;++e)u.metric.ddg[d][e][i][j]=u.metric.ddg[d][e][j][i]=g.dd[d][e];}}for(int i=0;i<3;++i){auto b=scalar(19+i),l=scalar(14+i);u.beta.value[i]=b.value;u.lambda.value[i]=l.value;for(int d=0;d<3;++d){u.beta.d[d][i]=b.d[d];u.lambda.d[d][i]=l.d[d];for(int e=0;e<3;++e)u.beta.dd[d][e][i]=b.dd[d][e];}}return u;}
void Faces(const char*filename,int A,int Nr){std::ifstream in(filename,std::ios::binary);std::uint64_t N,C;in.read(reinterpret_cast<char*>(&N),8);in.read(reinterpret_cast<char*>(&C),8);if(C!=300)throw std::runtime_error("snapshot ABI");std::vector<Real>data(N*C);in.read(reinterpret_cast<char*>(data.data()),data.size()*8);if(!in)throw std::runtime_error("short snapshot");size_t start=0;while(start<N&&data[start*C+13]==0)++start;if(N-start!=6*A*A*Nr)throw std::runtime_error("shell ordering");cs::Map map;map.L=.15;map.R=.7;h::LayerReference<Real>reference(1.,.5,{true,.05,.95});const Real E[4]={2.1875,-2.1875,1.3125,-.3125};int count=0;Real error=0,speed=-1e300,maxRows=0;
 for(int patch=0;patch<6;++patch)for(int k=0;k<A;++k)for(int j=0;j<A;++j){Real q[3]={1,-1+(j+.5)*2/A,-1+(k+.5)*2/A};auto face=map.Geometry(patch,q);auto ref=reference.At(face.x[0],face.x[1],face.x[2]);std::array<Real,184>flat{};for(int d=0;d<4;++d){size_t index=start+((patch*A+k)*A+j)*Nr+Nr-1-d;auto row=data.data()+index*C;auto node=Passive(row);auto r=reference.At(row[0],row[1],row[2]);Real nq[3]={(Nr-.5-d)/Nr,q[1],q[2]};auto ng=map.Geometry(patch,nq);for(int axis=0;axis<3;++axis)if(fabs(row[axis]-ng.x[axis])>1e-12)throw std::runtime_error("passive face geometry mismatch");std::array<Real,184>nv{},rv{};cs::typed_support::Map<Real>(node,[&](int i,Real x){nv[i]=x;return x;});cs::typed_support::Map<Real>(r.state,[&](int i,Real x){rv[i]=x;return x;});for(int i=0;i<184;++i)flat[i]+=(nv[i]-rv[i])*E[d];}

 auto u=cs::typed_support::Map<Real>(ref.state,[&](int i,Real x){return x+flat[i];});Real n[3],norm=0;for(int i=0;i<3;++i)norm+=face.J[0][i]*face.J[0][i];norm=sqrt(norm);for(int i=0;i<3;++i)n[i]=face.J[0][i]/norm;cs::native_face_boundary::Boundary b;if(!b.Build(u,n,ref.omega))throw std::runtime_error("native face not admissible");if(!(b.beta<0&&b.c+b.beta>0))throw std::runtime_error("native finite incoming branch invalid");Real amp[10],rows[10];b.Rows(u,ref.state,rows);for(int i=0;i<10;++i){amp[i]=.01*cos(Real((count+1)*(i+1)));maxRows=std::max(maxRows,fabs(rows[i]));}h::Z4cRHS<Real>penalty{};b.NativeLift(u,ref.omega,amp,penalty);auto projected=penalty;cs::native_algebraic_rhs::Tangent(u.metric,u.a,projected);error=std::max(error,MatrixDifference(penalty,projected));h::Z4cRHS<Real>base{};for(int i=0;i<3;++i)for(int z=0;z<3;++z){base.metric[i][z]=sin(Real(i+z+count+1));base.a[i][z]=cos(Real(i+z+count+2));}auto sum=base;for(int i=0;i<3;++i)for(int z=0;z<3;++z){sum.metric[i][z]+=penalty.metric[i][z];sum.a[i][z]+=penalty.a[i][z];}cs::native_algebraic_rhs::Tangent(u.metric,u.a,base);cs::native_algebraic_rhs::Tangent(u.metric,u.a,sum);for(int i=0;i<3;++i)for(int z=0;z<3;++z)error=std::max(error,fabs(sum.a[i][z]-base.a[i][z]-penalty.a[i][z]));speed=std::max(speed,-b.c-b.beta);++count;}
 std::cout<<"{\"native_face_points\":"<<count<<",\"lift_change\":"<<error<<",\"max_incoming_speed\":"<<speed<<",\"max_actual_rows\":"<<maxRows<<"}\n";}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int status=0;try{if(argc==4)Faces(argv[1],std::stoi(argv[2]),std::stoi(argv[3]));else while(std::cin>>std::ws,std::cin.peek()!=EOF){int id=Read(),mode=Read();Real x[3];for(auto&v:x)v=Read();h::Z4cJet<Real>empty{};auto u=cs::typed_support::Map<Real>(empty,[](int,Real){return Read();});Point(id,mode,u,x);}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
